// === Tab: mySketch ===
// Inspired (and helped) by @mathelirium on http://x.com/mathelirium/status/1976867742742397176

let theShader;

function preload() {
  vertShader = `
  precision highp float;
  attribute vec3 aPosition;
  attribute vec2 aTexCoord;
  varying vec2 vTexCoord;
  void main() {
    vTexCoord = aTexCoord;
    gl_Position = vec4(aPosition, 1.0);
  }`;

  fragShader = `
  precision highp float;

  uniform vec2 u_resolution;
  uniform float u_time;
  varying vec2 vTexCoord;

  // Complex functions
  vec2 c_add(vec2 a, vec2 b){ return a + b; }
  vec2 c_sub(vec2 a, vec2 b){ return a - b; }
  vec2 c_mul(vec2 a, vec2 b){ return vec2(a.x * b.x - a.y * b.y, a.x * b.y + a.y * b.x); }
  vec2 c_div(vec2 a, vec2 b){
	  float d = b.x*b.x + b.y*b.y + 1e-6;
    return vec2((a.x*b.x + a.y*b.y)/d, (a.y*b.x - a.x*b.y)/d);
  }
  float c_mag(vec2 z){ return length(z); }
  float c_arg(vec2 z){ return atan(z.y, z.x); }

  void main(){
    // normalize and center coordinates in complex plane
    vec2 uv = vTexCoord * 2.0 - 1.0;
    uv.x *= u_resolution.x / u_resolution.y;
    vec2 z = uv;

    // zeros and poles a_j and b_k
    vec2 zeros[2];
    vec2 poles[2];

    zeros[0] = 0.6 * vec2(sin(u_time * 0.8), cos(u_time * 0.6));
    zeros[1] = 0.6 * vec2(sin(u_time * 0.9 + 2.1), cos(u_time * 0.7 + 1.5));

    poles[0] = 0.6 * vec2(sin(u_time * 0.7 + 1.0), cos(u_time * 0.8 + 0.5));
    poles[1] = 0.6 * vec2(sin(u_time * 1.1 + 3.0), cos(u_time * 1.3 + 2.0));

    // implementing sum-based rational function
    // S(z) = Σ [w_j / (z - a_j)] - Σ [v_k / (z - b_k)]
    // each zero acts like a “positive charge”
    // each pole acts like a “negative charge”
    vec2 S = vec2(0.0);
    for (int i = 0; i < 2; i++) {
      vec2 wj = vec2(1.0, 0.0); // equal weights
      S += c_div(wj, c_sub(z, zeros[i]));
    }
    for (int i = 0; i < 2; i++) {
      vec2 vk = vec2(1.0, 0.0);
      S -= c_div(vk, c_sub(z, poles[i]));
    }

    // extract magnitude |S(z)| and phase arg(S(z))
    float mag = c_mag(S);
    float arg = c_arg(S);

    // logarithmic scaling to control field extreems
    float m = log(mag + 1.0);
    float inv = log(1.0/mag + 1.0);
    float balance = 0.4 * (m + inv);
    float bright = pow(balance, 2.0);

    // color based on phase
    vec3 base = 0.6 + 0.4 * cos(arg + vec3(0.0, 2.0, 4.0) + u_time * 0.2);

    // iso phase white field contour lines
    // sin(arg * PI) ≈ 0 gives phase boundaries

    float shimmer = 0.5 + 0.5 * sin(u_time * 2.0 + mag * 3.0);
    float lines = smoothstep(0.12, 0.0, abs(sin(arg * 3.14159 * 1.0 + shimmer)));
    base = mix(base, vec3(1.0), lines * 0.9);

    // localized brightness enhance near poles and zeros
    // as like electric field intensity
    float near = 0.0;
    for (int i=0; i<2; i++) {
      near += exp(-5.0 * length(z - zeros[i]));
      near += exp(-5.0 * length(z - poles[i]));
    }
    bright += 0.2 * near;

    // adding a vignette
    vec3 color = base * bright;
    float vignette = smoothstep(1.1, 0.3, length(uv));
    color *= vignette;

    gl_FragColor = vec4(color, 1.0);
  }`;
}

function setup() {
  createCanvas(700, 700, WEBGL);
  background(0, 0, 40);
  theShader = createShader(vertShader, fragShader);
}

function draw() {
  shader(theShader);
  theShader.setUniform("u_time", millis() / 3000.0);
  theShader.setUniform("u_resolution", [width, height]);
  beginShape(TRIANGLE_STRIP);
  vertex(-1, -1, 0, 0, 0);
  vertex(1, -1, 0, 1, 0);
  vertex(-1, 1, 0, 0, 1);
  vertex(1, 1, 0, 1, 1);
  endShape();
}

